// Demo: Architect drill - design a full Optical Character Recognition Trainer pipeline
(function(){'use strict';
var DATA={"label": "Architect drill - design a full Optical Character Recognitio", "rows": [["OpenCV", "15"], ["  OpenCV ", "87"], ["ResNet", "42"], ["YOLO", "55"], ["  YOLO ", "44"], ["Vision Transformers", "15"], ["Tesseract", "65"], ["  Tesseract ", "10"], ["", ""], ["OpenCV", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
console.log('Cleaning '+DATA.rows.length+' rows ('+DATA.label+'):');
DATA.rows.forEach(function(r){
  var cells=r.map(function(c){return String(c).trim();});
  if(cells.every(function(c){return c==='';})){droppedEmpty++;return;}
  var key=cells.join('|').toLowerCase();
  if(seen[key]){droppedDup++;return;}
  seen[key]=1;kept.push(cells);});
kept.forEach(function(r){console.log('  '+r.join(' | '));});
console.log('kept='+kept.length+' dropped_empty='+droppedEmpty+' dropped_dup='+droppedDup);
})();
